def evaluate_role(object, role):
    """
    Evaluate a role (sales, wholesale, manufacturing) based on given attributes.
    object: An object with attributes to be evaluated.
    role: The role to evaluate (sales, wholesale, manufacturing).
    Returns: The computed score.
    """
    score = 0
    # Define the attributes and their scoring for each role
    role_attributes = {
        'sales': {
            'sales_skills': {'thresholds': [8, 5], 'points': [2, 1]},
            'communication_skills': {'thresholds': [8, 5], 'points': [2, 1]},
            'relationship_management': {'thresholds': [8, 5], 'points': [2, 1]},
            'product_knowledge': {'thresholds': [7, 5], 'points': [2, 1]},
            'age': {'thresholds': ['elder', 'middle', 'young'], 'points': [2, 1]}
        },
        'wholesale': {
            'product_knowledge': {'thresholds': [9, 5], 'points': [2, 1]},
            'communication_skills': {'thresholds': [7, 5], 'points': [2, 1]},
            'negotiation_skills': {'thresholds': [8, 5], 'points': [2, 1]},
            'experience': {'thresholds': ['elder', 'middle', 'young'], 'points': [2, 1]}
        },
        'manufacturing': {
            'technical_skills': {'thresholds': [9, 5], 'points': [2, 1]},
            'problem_solving': {'thresholds': [8, 5], 'points': [2, 1]},
            'process_optimization': {'thresholds': [7, 5], 'points': [2, 1]},
            'leadership': {'thresholds': [8, 5], 'points': [2, 1]},
            'age': {'thresholds': ['elder', 'middle', 'young'], 'points': [2, 1]}
        }
    }

    # Check each attribute for the given role
    for attr, attr_info in role_attributes[role].items():
        value = getattr(object, attr)
        if attr == 'age':
            if value == 'elder':
                score += attr_info['points'][1]
            else:
                score += attr_info['points'][0]
        else:
            if isinstance(value, int):
                if value >= attr_info['thresholds'][0]:
                    score += attr_info['points'][1]
                else:
                    score += attr_info['points'][0]
            else:
                if value == attr_info['thresholds'][1]:
                    score += attr_info['points'][1]
                else:
                    score += attr_info['points'][0]

    return score

